-------------------------------

-- Force reload of all modules on hyprctl reload
for k in pairs(package.loaded) do
    if k:match("^modules%.") then
        package.loaded[k] = nil
    end
end

require("modules.env")
require("modules.monitors")
require("modules.input")
require("modules.general")
require("modules.decorations")
require("modules.animations")
require("modules.layerrules")
require("modules.windowrules")
require("modules.binds")
require("modules.autostart")

-- Include dynamic colors generated by Matugen if available
local colors = os.getenv("HOME") .. "/.config/hypr/colors.lua"
local f = io.open(colors, "r")
if f then
    f:close()
    package.loaded["colors"] = nil
    pcall(dofile, colors)
end

